model_templates={}
def mt(name,cond,direction,meaning):
 model_templates[name]={'entry':AND(model_context_entry,cond),'direction':direction,'requires':requires([model_context_entry,cond,direction]),'exit':{'anchor':'opportunity.origin_ns','duration':'task.horizon_s','late_policy':'NO_ENTRY_EXPIRED if actual eligible submit time>=origin+h'},'meaning':meaning,'raw_prediction_policy':'No new clipping or support-based exclusion. Source-defined transforms/clamps stay versioned;retain raw_pretransform if actually available,never reconstruct an unobserved raw value from clipped source output.'}
mt('signed_source_spread',gt(ABS(F('model.prediction')),F('quote.spread_price_units')),SIGN(F('model.prediction')),'Recovered signed diagnostic direction/activation;platform execution new. Source zero/weak cases remain logged.')
mt('signed_new_weak',O('le',ABS(F('model.prediction')),F('quote.spread_price_units')),SIGN(F('model.prediction')),'NEW weak-output direction arm;zero=>ZERO_DIRECTION_NO_ORDER,never zero-return trade.')
for cell,cond in [('above_spread',gt(F('model.prediction'),F('quote.spread_price_units'))),('at_or_below_spread',O('le',F('model.prediction'),F('quote.spread_price_units')))]:
 for side,d in [('long',1),('short',-1)]:mt('absolute_'+cell+'_'+side,cond,C(d),'NEW common absolute-endpoint target translation;both cells and both sides retained. Negative raw magnitude stays tagged INVALID_TARGET_SUPPORT but finite output remains contextual,not missing.')
for cell,cond in [('high',ge(F('model.prediction'),C(0.5))),('low',lt(F('model.prediction'),C(0.5)))]:
 for side,d in [('long',1),('short',-1)]:mt('occurrence_'+cell+'_'+side,cond,C(d),'NEW common probability-context translation. Out-of-[0,1]finite values retain high/low placement plus INVALID_PROBABILITY_SUPPORT tag. No silent clipping.')
for t in model_map:
 if t['target']=='mid_price_change':t['recipe_templates']=['signed_source_spread','signed_new_weak']
 elif t['target']=='absolute_mid_price_change':t['recipe_templates']=['absolute_'+c+'_'+s for c in ['above_spread','at_or_below_spread'] for s in ['long','short']]
 elif t['target']=='first_observed_family_within_h':t['recipe_templates']=['occurrence_'+c+'_'+s for c in ['high','low'] for s in ['long','short']]
 else:t['recipe_templates']=[];t['unresolved_target_translation']=True
